-- Nov 11 2026 additions: Project K trial-deck versions + pictures, Arcane Collector Boxes,
-- red / pink / silver sealed packs, Blade of the Ruined King playmat merge, Origins case print runs.
-- Safe to run more than once.

insert into promo_items (id, r, data)
select v.id, v.r, v.data || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
from (values
  ('item-10600', 10600, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "By itself", "cat": "PROMO + COLLECTIBLE", "nm": "Machine Herald [Project K Trial Deck]", "ty": "Card", "cn": "265", "ra": "Legend", "do": "Mind\nOrder", "tg": "Legend\nViktor\nProject K\nSample", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/machine-herald-project-k-trial-deck-sample-ch-item-10600.webp", "inf": "Project K trial-deck version of this legend. These came inside the Chinese Project K trial decks (Viktor, Jinx, Volibear, Yasuo) handed out at the December 2024 Macau event before the game was revealed as Riftbound. Same card as the Macau silver-pack promo, but non-foil with SAMPLE printed across the front. Trial-deck cards also turn up on eBay as singles.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.", "r": 10600, "id": "item-10600"}$j$::jsonb),
  ('item-10601', 10601, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "By itself", "cat": "PROMO + COLLECTIBLE", "nm": "Immortal Madness [Project K Trial Deck]", "ty": "Card", "cn": "249", "ra": "Legend", "do": "Fury\nBody", "tg": "Legend\nVolibear\nProject K\nSample", "inf": "Project K trial-deck version of this legend. These came inside the Chinese Project K trial decks (Viktor, Jinx, Volibear, Yasuo) handed out at the December 2024 Macau event before the game was revealed as Riftbound. Same card as the Macau silver-pack promo, but non-foil with SAMPLE printed across the front. Trial-deck cards also turn up on eBay as singles.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.", "r": 10601, "id": "item-10601"}$j$::jsonb),
  ('item-10602', 10602, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "By itself", "cat": "PROMO + COLLECTIBLE", "nm": "Loose Cannon [Project K Trial Deck]", "ty": "Card", "cn": "251", "ra": "Legend", "do": "Fury\nChaos", "tg": "Legend\nJinx\nProject K\nSample", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/loose-cannon-project-k-trial-deck-sample-ch-item-10602.webp", "inf": "Project K trial-deck version of this legend. These came inside the Chinese Project K trial decks (Viktor, Jinx, Volibear, Yasuo) handed out at the December 2024 Macau event before the game was revealed as Riftbound. Same card as the Macau silver-pack promo, but non-foil with SAMPLE printed across the front. Trial-deck cards also turn up on eBay as singles.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.", "r": 10602, "id": "item-10602"}$j$::jsonb),
  ('item-10603', 10603, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "By itself", "cat": "PROMO + COLLECTIBLE", "nm": "Gale Swordsman [Project K Trial Deck]", "ty": "Card", "cn": "259", "ra": "Legend", "do": "Calm\nChaos", "tg": "Legend\nYasuo\nProject K\nSample", "inf": "Project K trial-deck version of this legend. These came inside the Chinese Project K trial decks (Viktor, Jinx, Volibear, Yasuo) handed out at the December 2024 Macau event before the game was revealed as Riftbound. Same card as the Macau silver-pack promo, but non-foil with SAMPLE printed across the front. Trial-deck cards also turn up on eBay as singles.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.", "r": 10603, "id": "item-10603"}$j$::jsonb),
  ('item-10604', 10604, $j${"cat": "COLLECTIBLE", "nm": "Arcane Collector Box", "la": "English", "ev": "Global regions excluding China", "se": "ARC", "ty": "Collector Box", "cn": "N/A", "ra": "Combination of Rarities", "do": "All Domains", "tg": "Arcane\nCollector Box", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Sealed box", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/arcane-collector-box-en-item-10604.webp", "inf": "Arcane Collector Box (English). Holds the six Arcane alternate-art cards: Vi - Destructive, Caitlyn - Patrolling, Heimerdinger - Inventor, Warwick - Hunter, Jinx - Rebel and Viktor - Leader. Sold online through the Riot Merch Store. Marking the box as owned also marks its six cards.", "r": 10604, "id": "item-10604"}$j$::jsonb),
  ('item-10605', 10605, $j${"cat": "COLLECTIBLE", "nm": "Arcane Collector Box", "la": "Chinese", "ev": "China", "se": "ARC", "ty": "Collector Box", "cn": "N/A", "ra": "Combination of Rarities", "do": "All Domains", "tg": "Arcane\nCollector Box", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Sealed box", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/arcane-collector-box-ch-item-10605.webp", "inf": "Arcane Collector Box (Chinese). Holds the six Chinese Arcane cards: Vi, Caitlyn, Heimerdinger, Warwick, Jinx and Viktor - Leader. Marking the box as owned also marks its six cards.", "r": 10605, "id": "item-10605"}$j$::jsonb),
  ('item-10606', 10606, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Sealed foil pack", "cat": "COLLECTIBLE", "nm": "Spring Festival Red Pack [Project K]", "ty": "Sealed Pack", "cn": "N/A", "ra": "Rare", "do": "N/A", "tg": "Project K\nSpring Festival\nLunar New Year\nSealed Pack", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/spring-festival-red-pack-project-k-ch-item-10606.webp", "inf": "Sealed red foil pack from the Chinese Spring Festival (Lunar New Year) promotion, back when the game was still called Project K. The single card from these packs, Teemo - Scout Spring Festival [Project K], is listed separately.", "r": 10606, "id": "item-10606"}$j$::jsonb),
  ('item-10607', 10607, $j${"la": "Chinese", "ev": "China", "se": "ARC", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Sealed foil pack", "cat": "COLLECTIBLE", "nm": "Arcane Immersive Music Experience Pack", "ty": "Sealed Pack", "cn": "PR-SCY01", "ra": "Rare", "do": "N/A", "tg": "Arcane\nImmersive Music Experience\nSealed Pack", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/arcane-immersive-music-pink-pack-ch-item-10607.webp", "inf": "Pink commemorative card pack given out at the Arcane Immersive Music Experience show in China (pack code PR-SCY01). Each sealed pack holds one promo card.", "r": 10607, "id": "item-10607"}$j$::jsonb),
  ('item-10608', 10608, $j${"la": "Chinese", "ev": "China", "se": "FND", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Sealed foil pack", "cat": "COLLECTIBLE", "nm": "Macau Event Silver Pack [Project K]", "ty": "Sealed Pack", "cn": "N/A", "ra": "Rare", "do": "N/A", "tg": "Project K\nMacau\nSealed Pack", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/macau-event-silver-pack-project-k-ch-item-10608.webp", "inf": "Sealed silver foil pack from the December 2024 Project K launch promotion in Macau, Shanghai and Chongqing. Each pack holds one random holo legend: Machine Herald (Viktor), Immortal Madness (Volibear), Loose Cannon (Jinx) or Gale Swordsman (Yasuo). Those four cards are listed separately as the [Macau] promos.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.", "r": 10608, "id": "item-10608"}$j$::jsonb)
) as v(id, r, data)
where not exists (select 1 from promo_items p where p.id = v.id);

update promo_items set data = data || '{"img": ""}'::jsonb
  || jsonb_build_object('inf', coalesce(data->>'inf','') || case when coalesce(data->>'inf','') like '%Grading heads-up%' then '' else '

Grading heads-up: PSA, Beckett and other graders don''t label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.' end)
where id = 'item-13';
update promo_items set data = data || '{}'::jsonb
  || jsonb_build_object('inf', coalesce(data->>'inf','') || case when coalesce(data->>'inf','') like '%Grading heads-up%' then '' else '

Grading heads-up: PSA, Beckett and other graders don''t label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.' end)
where id = 'item-14';
update promo_items set data = data || '{"img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/loose-cannon-macau-holo-ch-item-15.webp"}'::jsonb
  || jsonb_build_object('inf', coalesce(data->>'inf','') || case when coalesce(data->>'inf','') like '%Grading heads-up%' then '' else '

Grading heads-up: PSA, Beckett and other graders don''t label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.' end)
where id = 'item-15';
update promo_items set data = data || '{}'::jsonb
  || jsonb_build_object('inf', coalesce(data->>'inf','') || case when coalesce(data->>'inf','') like '%Grading heads-up%' then '' else '

Grading heads-up: PSA, Beckett and other graders don''t label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.' end)
where id = 'item-16';
update promo_items set data = data || '{"img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/viktor-project-k-trial-deck-ch-item-20.webp"}'::jsonb
where id = 'item-20';

-- Blade of the Ruined King playmat: one entry listing all four Regional Qualifiers.
update promo_items set data = data || jsonb_build_object(
  'ev', 'RQ - Atlanta, GA USA' || chr(10) || 'RQ - Bologna, Italy' || chr(10) || 'RQ - Las Vegas, NV USA' || chr(10) || 'RQ - Lille, France',
  'inf', 'Regional Qualifier Champion prize playmat. The same playmat was given to the champion at the Atlanta, Bologna, Las Vegas and Lille Regional Qualifiers.')
where id = 'item-10075';
delete from promo_items where id in ('item-10080','item-10111','item-10116');

-- Origins booster case: one entry, members pick First or Second Print in the details.
update promo_items set data = data || jsonb_build_object('nm','Origins Booster Box Case','tg','First Print' || chr(10) || 'Second Print')
where id = 'item-318';
delete from promo_items where id = 'item-319';

